import{_ as r,a0 as o,w as a,s as d,I as n,x as u,a1 as i,A as p,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"精简版 Xubuntu：建立你自己的发行版的机会 | LCTT x X-CMD","titleTemplate":false,"description":"精简版 Xubuntu：建立你自己的发行版的机会 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精简版 Xubuntu：建立你自己的发行版的机会 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精简版 Xubuntu：建立你自己的发行版的机会 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro","title":"精简版 Xubuntu：建立你自己的发行版的机会","tag":"202303","desc":""},"relativePath":"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro.md","filePath":"[post].md"}'),b={name:"202303/20230306.0 ⭐️ Xubuntu Minimal Opportunity to Build Your Own Distro.md"};function e(m,t,f,w,x,X){const l=o("Link");return a(),d("div",null,[t[26]||(t[26]=n("h1",{id:"精简版-xubuntu-建立你自己的发行版的机会",tabindex:"-1"},[u("精简版 Xubuntu：建立你自己的发行版的机会 "),n("a",{class:"header-anchor",href:"#精简版-xubuntu-建立你自己的发行版的机会","aria-label":"Permalink to “精简版 Xubuntu：建立你自己的发行版的机会”"},"​")],-1)),t[27]||(t[27]=n("blockquote",null,[n("p",null,"Xubuntu 团队从 23.04 版本开始推出了一个包含少量组件的精简 ISO。以下是它的情况。")],-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/03/xubuntu1.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=u("几天前，Canonical ",-1)),i(l,{href:"https://linux.cn/article-15588-1.html"},{default:p(()=>[...t[0]||(t[0]=[u("宣布",-1)])]),_:1}),t[2]||(t[2]=u("，Ubuntu 23.04 “Lunar Lobster” 版本官方的精简 ISO 安装文件正在制作中。虽然截至发稿时，该镜像还没有出现，但 Xubuntu 团队设法推出了他们自己的精简 ISO 安装镜像。",-1))]),t[29]||(t[29]=s('<p>Xubuntu 被数百万人使用，并且一直是许多其他发行版的基础。对于一些用户来说，默认安装可能带有太多的预装包和功能，导致系统臃肿，计算机性能降低。这就是 Xubuntu 精简安装发挥作用的地方。在这篇文章中，我们将采取实践的方式来安装和探索精简版 Ubuntu 的功能。</p><p>让我们看看你在 Xubuntu 精简安装中得到了什么，以及与普通桌面安装程序的比较。</p><h3 id="xubuntu-精简安装" tabindex="-1">Xubuntu 精简安装 <a class="header-anchor" href="#xubuntu-精简安装" aria-label="Permalink to “Xubuntu 精简安装”">​</a></h3><p>第一个明显的区别是精简安装与标准桌面安装程序的 ISO 镜像大小。它的大小大约减少了 39%。</p><div class="table-wrap"><table><thead><tr><th></th><th>精简版</th><th>标准版</th></tr></thead><tbody><tr><td>桌面安装程序（ISO）大小</td><td>1.7 GB</td><td>2.8 GB</td></tr></tbody></table></div><p>在使用精简版安装程序安装 Xubuntu 时，你不会在 Ubiquity 中看到“<ruby>精简安装<rt>minimal install</rt></ruby>”的选项。其余的安装步骤都是一样的，没有区别。</p><p>然而，主要的区别是在安装的系统上。最小安装只需要 7.2GB 的磁盘空间，而同一版本的标准安装则需要 11GB。</p><div class="table-wrap"><table><thead><tr><th></th><th>精简版</th><th>标准版</th></tr></thead><tbody><tr><td>磁盘使用空间</td><td>7.2 GB</td><td>11 GB</td></tr></tbody></table></div><p>因为许多应用程序被剥离了。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/03/Xubuntu-minimal-and-standard-install-comparison.jpg" alt="Xubuntu 精简和标准安装比较"></p><p>在 Xubuntu 的精简安装中，你会得到以下东西：</p><ul><li>终端</li><li>文件管理器</li><li>所有的设置应用</li><li>Synaptic 包管理器</li><li>屏幕截图应用</li></ul><p>就这些了。</p><p>如果你把它与标准版相比，你就不会有以下的应用：</p><ul><li>Firefox 浏览器</li><li>Thunderbird 邮件客户端</li><li>媒体播放器（音频和视频）</li><li>LibreOffice 套件</li><li>Transmission Torrent 客户端</li><li>GNOME 软件</li><li>游戏</li><li>Gigolo 远程连接客户端</li><li>磁盘使用工具</li></ul><h3 id="精简版-xubuntu-上的-snap-包" tabindex="-1">精简版 Xubuntu 上的 Snap 包 <a class="header-anchor" href="#精简版-xubuntu-上的-snap-包" aria-label="Permalink to “精简版 Xubuntu 上的 Snap 包”">​</a></h3><p>令我惊讶的是，精简版 Xubuntu 没有安装 Snap！甚至连 Snap 守护程序都没有。而且也没有 Flatpak。</p><p>所以，实际上你得到的是一个没有 Snap 的 Xubuntu 系统，但有一个核心的 Ubuntu 基础。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/03/Look-no-snap.jpg" alt="看，没有 Snap"></p><p>但我不确定主 Ubuntu 的精简 ISO 会有同样的情况。我想我们需要等待和观察。</p><h3 id="接下来是什么" tabindex="-1">接下来是什么？ <a class="header-anchor" href="#接下来是什么" aria-label="Permalink to “接下来是什么？”">​</a></h3><p>所以，现在你有了一个初级的 Xubuntu 桌面。使用 Synaptic 包管理器，你可以开始构建和安装你喜欢的应用。</p>',22)),n("p",null,[t[4]||(t[4]=u("例如，你可以 ",-1)),i(l,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:p(()=>[...t[3]||(t[3]=[u("设置 Flatpak",-1)])]),_:1}),t[5]||(t[5]=u(" 并从一个基本的浏览器、媒体播放器、LibreOffice 等开始。",-1))]),t[30]||(t[30]=n("p",null,"如果你是一个开发者，你可以安装 Visual Studio Code 或一些 IDE。",-1)),t[31]||(t[31]=n("p",null,"以这个版本为基础，你可以为你的工作流程建立任何发行版。",-1)),t[32]||(t[32]=n("h3",{id:"总结",tabindex:"-1"},[u("总结 "),n("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[33]||(t[33]=n("p",null,"Xubuntu 精简安装对于那些想要完全控制他们系统上安装的东西，并且喜欢更快、更有效的基于 Ubuntu 的发行版的用户来说是一个很好的选择。",-1)),t[34]||(t[34]=n("p",null,"Xfce 的可定制性、轻量级特性和使用 synaptic 的包管理使它成为任何定制构建的理想选择。",-1)),n("p",null,[t[7]||(t[7]=u("你可以从这个 ",-1)),i(l,{href:"https://cdimage.ubuntu.com/xubuntu/daily-live/current/"},{default:p(()=>[...t[6]||(t[6]=[u("页面",-1)])]),_:1}),t[8]||(t[8]=u(" 下载精简版 ISO。记住，它还没有正式发布，而且是一个日常构建的副本。所以使用它要",-1)),t[9]||(t[9]=n("strong",null,"谨慎",-1)),t[10]||(t[10]=u("。",-1))]),t[35]||(t[35]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=u("via: ",-1)),i(l,{href:"https://www.debugpoint.com/xubuntu-minimal/"},{default:p(()=>[...t[11]||(t[11]=[u("https://www.debugpoint.com/xubuntu-minimal/",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=u("作者：",-1)),i(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...t[13]||(t[13]=[u("Arindam",-1)])]),_:1}),t[18]||(t[18]=u(" 选题：",-1)),i(l,{href:"https://github.com/lkxed/"},{default:p(()=>[...t[14]||(t[14]=[u("lkxed",-1)])]),_:1}),t[19]||(t[19]=u(" 译者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:p(()=>[...t[15]||(t[15]=[u("geekpi",-1)])]),_:1}),t[20]||(t[20]=u(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[16]||(t[16]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=u("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[21]||(t[21]=[u("LCTT",-1)])]),_:1}),t[24]||(t[24]=u(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:p(()=>[...t[22]||(t[22]=[u("Linux中国",-1)])]),_:1}),t[25]||(t[25]=u(" 荣誉推出",-1))])])}const O=r(b,[["render",e]]);export{S as __pageData,O as default};
